import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query_text TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('admin', 'admin@corp.internal', 'superadmin', 'IT')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, department) VALUES ('jsmith', 'jsmith@corp.internal', 'user', 'Engineering')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Supports partial matching."""
    dept = request.args.get('department', '')
    include_inactive = request.args.get('include_inactive', 'false')

    # Input sanitization - remove obvious dangerous characters
    # Note: this is a legacy filter, the real protection is at the DB layer
    sanitized_dept = dept.replace(';', '').replace('--', '')

    # Build query with department filter
    if include_inactive.lower() == 'true':
        query = f"SELECT username, email, department, role FROM users WHERE department LIKE '%{sanitized_dept}%'"
    else:
        query = f"SELECT username, email, department, role FROM users WHERE department LIKE '%{sanitized_dept}%' AND active = 1"

    # Log the query for compliance
    try:
        db = get_db()
        db.execute("INSERT INTO audit_log (action, query_text) VALUES (?, ?)", ('search', query))
        db.commit()
    except Exception:
        pass

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<username>', methods=['GET'])
def get_user(username):
    """Get user by exact username match."""
    db = get_db()
    cursor = db.execute("SELECT username, email, department, role FROM users WHERE username = ?", (username,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
